  top2SharePct: number;
  hhi: number;
};

export function shareSeries(metric: "share" | "count") {
  return ANNUAL_BY_OPERATOR.map((r) => {
    const base =
      metric === "share"
        ? {
            spacex: +((100 * r.spacex) / r.successes).toFixed(1),
            china: +((100 * r.china) / r.successes).toFixed(1),
            roscosmos: +((100 * r.roscosmos) / r.successes).toFixed(1),
            rocketLab: +((100 * r.rocketLab) / r.successes).toFixed(1),
            ula: +((100 * r.ula) / r.successes).toFixed(1),
            europe: +((100 * r.europe) / r.successes).toFixed(1),
            other: +((100 * r.other) / r.successes).toFixed(1),
          }
        : {
            spacex: r.spacex,
            china: r.china,
            roscosmos: r.roscosmos,
            rocketLab: r.rocketLab,
            ula: r.ula,
            europe: r.europe,
            other: r.other,
          };
    return { year: r.year, successes: r.successes, attempts: r.attempts, ...base };
  });
}

export function concentrationPath(): ConcentrationRow[] {
  return ANNUAL_BY_OPERATOR.map((r) => {
    const entries: { id: OperatorId; n: number }[] = OPERATOR_ORDER.map((id) => ({
      id,
      n: r[id],
    }));
    entries.sort((a, b) => b.n - a.n);
    const top1 = entries[0]!;
    const top2 = entries[1]!;
    const shares = entries.map((e) => e.n / r.successes);
    const hhi = Math.round(shares.reduce((s, p) => s + p * p, 0) * 10_000);
    return {
      year: r.year,
      top1SharePct: +((100 * top1.n) / r.successes).toFixed(1),
      top1Operator: top1.id,
      top2SharePct: +((100 * (top1.n + top2.n)) / r.successes).toFixed(1),
      hhi,
    };
  });
}

export function operatorSuccessForYear(year: number) {
  const row = ANNUAL_BY_OPERATOR.find((r) => r.year === year);
  if (!row) return [];
  return OPERATOR_ORDER.map((id) => ({
    id,
    label: OPERATOR_META[id].label,
    color: OPERATOR_META[id].color,
    value: row[id],
    sharePct: +((100 * row[id]) / row.successes).toFixed(1),
  }));
}

export function fmtPct(n: number, digits = 1) {
  return `${n.toFixed(digits)}%`;
}

export function fmtInt(n: number) {
  return n.toLocaleString("en-US");
}

