/**
 * QA: orbital-launch-cadence-by-operator-2026
 * // viz-types: stacked-area shares, year donut, dual-lens bars, concentration line+scatter, quarterly composed, Starlink mix | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  ANNUAL_BY_OPERATOR,
  HEADLINE,
  SPACEX_MISSION_MIX,
} from "../src/data/orbital-launch-cadence-by-operator-2026-data.ts";

assert.equal(HEADLINE.spacexSharePct2025, 51.4);
assert.equal(HEADLINE.spacexSharePct2020, 22.7);
assert.equal(HEADLINE.spacexSharePpDelta, 28.7);
assert.equal(HEADLINE.spacexSuccess2025, 165);
assert.equal(HEADLINE.globalSuccess2025, 321);
assert.equal(HEADLINE.chinaSuccess2025, 90);
assert.equal(ANNUAL_BY_OPERATOR.length, 6);
assert.equal(ANNUAL_BY_OPERATOR.at(-1)?.year, 2025);
assert.equal(SPACEX_MISSION_MIX.at(-1)?.starlinkMissions, 123);

const root = process.cwd();
const slug = "orbital-launch-cadence-by-operator-2026";
const markers = [
  "Orbital launch cadence by operator ??? Technology / orbital-space",
  "Operator share of successful orbital launches, 2020???2025",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4182);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(
      '[data-viz="orbital-launch-cadence-by-operator-2026"]',
      { timeout: 20000 },
    );
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({
        state: "attached",
        timeout: 20000,
      });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Share %");
    await clickBtn(page, "Launch count");
    await clickBtn(page, "2023");
    await clickBtn(page, "2025");
    await clickBtn(page, "Count vs mass");
    await clickBtn(page, "Cadence & mix");
    await clickBtn(page, "Operator share");
    console.log("??? auditVizInteractions");
    const audit = await auditVizInteractions(page);
    if (audit.issues.length > 0) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    console.log("??? viz interaction audit");
    console.log(`??? QA passed for ${slug}`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

